			move.b (a0)+, (a1)+
			dbeq d1, p_chks_si0
			beq p_chks_si0_z
p_chks_si0_e:
			clr.b (a1)
p_chks_si0_z:
			movea.l (sp)+, a0		; want
			lea var_chks_want, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_chks_si1_e
p_chks_si1:
			move.b (a0)+, (a1)+
			dbeq d1, p_chks_si1
			beq p_chks_si1_z
p_chks_si1_e:
			clr.b (a1)
p_chks_si1_z:
			move.l sp, p_chks_rs
			lea p_chks, sp
			rts
p_chks_r:		; end of chks
			movea.l p_chks_rs, sp
			rts
p_sumof_c:		; call sumof
			movea.l (sp)+, a0		; v() descriptor
			lea pa_sumof_v, a1
			move.l (a0)+, (a1)+
