			bne kw_lk_cmp
			addq.l #1, a0
			move.b (a0), d6
			cmpi.b #']', d6
			beq kw_lk_dash
			tst.b d6
			beq kw_lk_back
			move.b d6, d3
			addq.l #1, a0
			bra kw_lk_cmp
kw_lk_dash:
			subq.l #1, a0
kw_lk_cmp:
			cmp.b d2, d1
			bcs kw_lk_cl
			cmp.b d3, d1
			bhi kw_lk_cl
			moveq #1, d5
			bra kw_lk_cl
kw_lk_clend:
			addq.l #1, a0
			cmp.b d4, d5
			beq kw_lk_back
			addq.l #1, a1
			bra kw_lk_lp
kw_lk_lit:
			cmp.b d0, d1
			bne kw_lk_back
			addq.l #1, a0
			addq.l #1, a1
			bra kw_lk_lp
kw_lk_back:
			cmpa.w #0, a2
			beq kw_lk_no
			addq.l #1, a3
			movea.l a3, a1
			movea.l a2, a0
			bra kw_lk_lp
kw_lk_end:
			move.b (a0), d0
			cmpi.b #'*', d0
			bne kw_lk_e2
			addq.l #1, a0
			bra kw_lk_end
kw_lk_e2:
			tst.b d0
			rts
kw_lk_no:
			moveq #1, d0
			rts

			even
;## kw_strlset
;kw_strlset, <dest>, <src>  - LSet dest = src: src left in dest's length, spaces after
kw_strlset:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			movea.l a1, a2
			moveq #0, d1
kw_ls_len:
			tst.b (a2)+
			beq kw_ls_go
			addq.w #1, d1
			bra kw_ls_len
kw_ls_go:
			tst.w d1
			beq kw_ls_e
			subq.w #1, d1
kw_ls_cp:
			move.b (a0), d0
			beq kw_ls_pad
			addq.l #1, a0
			move.b d0, (a1)+
			dbra d1, kw_ls_cp
kw_ls_e:
			rts
kw_ls_pad:
			move.b #' ', (a1)+
			dbra d1, kw_ls_pad
			rts

			even
;## kw_strrset
;kw_strrset, <dest>, <src>  - RSet dest = src: src right in dest's length, spaces before
kw_strrset:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			movea.l a1, a2
			moveq #0, d1
kw_rs_len:
			tst.b (a2)+
			beq kw_rs_l2
			addq.w #1, d1
			bra kw_rs_len
kw_rs_l2:
			movea.l a0, a2
			moveq #0, d2
kw_rs_len2:
			tst.b (a2)+
			beq kw_rs_go
			addq.w #1, d2
			bra kw_rs_len2
kw_rs_go:
			tst.w d1
			beq kw_rs_e
			cmp.w d1, d2
			bcs kw_rs_pad
			subq.w #1, d1
kw_rs_cp:
			move.b (a0)+, (a1)+
			dbra d1, kw_rs_cp
kw_rs_e:
			rts
kw_rs_pad:
			move.w d1, d3
			sub.w d2, d3
			subq.w #1, d3
kw_rs_p:
			move.b #' ', (a1)+
			dbra d3, kw_rs_p
			tst.w d2
			beq kw_rs_e
			move.w d2, d1
			subq.w #1, d1
			bra kw_rs_cp

			even
;## kw_strfix
;kw_strfix, <var>, <n>  - String * n after a change: pad with spaces / cut to n
kw_strfix:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			andi.w #$FF, d1
			beq kw_sf_end
			subq.w #1, d1
kw_sf_len:
			tst.b (a0)
			beq kw_sf_pad
			addq.l #1, a0
			dbra d1, kw_sf_len
			clr.b (a0)
			rts
kw_sf_pad:
			move.b #' ', (a0)+
			dbra d1, kw_sf_pad
kw_sf_end:
			clr.b (a0)
			rts

			even
;## ntc_fmt ntc_data
; Format$ with a number pattern. ntc_fmbuf holds "-123"; the thread has
; <mindigits>, <group>, <prefix>, <suffix>. a1 = the dest. rts (thread)
ntc_fm_common:
			move.l (sp)+, d4			; mindigits
			move.l (sp)+, d5			; group
			movea.l (sp)+, a2			; prefix
			movea.l (sp)+, a3			; suffix
			lea ntc_fmbuf, a0
			cmpi.b #'-', (a0)
			bne ntc_fm_pos
			move.b (a0)+, (a1)+
ntc_fm_pos:
ntc_fm_pre:
			move.b (a2)+, d0
			beq ntc_fm_cnt
			move.b d0, (a1)+
			bra ntc_fm_pre
ntc_fm_cnt:
			movea.l a0, a2				; the digits
			moveq #0, d1
ntc_fm_c1:
			tst.b (a2)+
			beq ntc_fm_c2
			addq.w #1, d1
			bra ntc_fm_c1
ntc_fm_c2:
			moveq #0, d2				; zeros in front
			andi.w #$FF, d4
			cmp.w d1, d4
			bls ntc_fm_c3
			move.w d4, d2
			sub.w d1, d2
ntc_fm_c3:
			move.w d1, d6
			add.w d2, d6				; digits to write
			move.w d6, d7
ntc_fm_mod:
			cmpi.w #4, d7
			bcs ntc_fm_out
			subq.w #3, d7
			bra ntc_fm_mod			; d7 = digits before the first comma
ntc_fm_out:
			tst.w d6
			beq ntc_fm_suf
			tst.w d2
			beq ntc_fm_d
			subq.w #1, d2
			move.b #'0', (a1)+
			bra ntc_fm_nx
ntc_fm_d:
			move.b (a0)+, (a1)+
ntc_fm_nx:
			subq.w #1, d6
			subq.w #1, d7
			bne ntc_fm_out
			moveq #3, d7
			tst.w d6
			beq ntc_fm_suf
			tst.w d5
			beq ntc_fm_out
			move.b #',', (a1)+
			bra ntc_fm_out
ntc_fm_suf:
			move.b (a3)+, (a1)+
			bne ntc_fm_suf
			rts

			even
;## kw_strfmt ntc_fmt ntc_itoa
;kw_strfmt, <dest>, <var>, <mindigits>, <group>, <prefix>, <suffix>  - Format$(n, "0,000")
kw_strfmt:
			movea.l (sp)+, a4			; dest
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_fmbuf, a1
			lea kw_sfm_b, a6
			bra ntc_itoa
kw_sfm_b:
			movea.l a4, a1
			bra ntc_fm_common

			even
;## kw_l_strfmt ntc_fmt ntc_ltoa
;kw_l_strfmt, <dest>, <long>, <mindigits>, <group>, <prefix>, <suffix>  - Format$ of a Long
kw_l_strfmt:
			movea.l (sp)+, a4
			movea.l (sp)+, a0
			move.l (a0), d0
			lea ntc_fmbuf, a1
			lea kw_lsfm_b, a6
			bra ntc_ltoa
kw_lsfm_b:
			movea.l a4, a1
			bra ntc_fm_common

			even
;## kw_strjoin
;kw_strjoin, <dest>, <descriptor>, <sep>  - Join(stringarray, sep), NTC_STRMAX characters at most
kw_strjoin:
			movea.l (sp)+, a4			; dest
			movea.l (sp)+, a0			; descriptor
			movea.w (a0), a2			; base (RAM)
			move.w 6(a0), d3			; count
			move.w 10(a0), d5			; element size
			movea.l (sp)+, a3			; sep
			lea ntc_jnbuf, a1
			move.w #NTC_STRMAX, d4
			tst.w d3
			beq kw_jn_done
kw_jn_el:
			movea.l a2, a0
kw_jn_c1:
			move.b (a0)+, d0
			beq kw_jn_eend
			tst.w d4
			beq kw_jn_done
			move.b d0, (a1)+
			subq.w #1, d4
			bra kw_jn_c1
kw_jn_eend:
			adda.w d5, a2
			subq.w #1, d3
			beq kw_jn_done
			movea.l a3, a0
kw_jn_c2:
			move.b (a0)+, d0
			beq kw_jn_el
			tst.w d4
			beq kw_jn_done
			move.b d0, (a1)+
			subq.w #1, d4
			bra kw_jn_c2
kw_jn_done:
			clr.b (a1)
			lea ntc_jnbuf, a0
kw_jn_out:
			move.b (a0)+, (a4)+
			bne kw_jn_out
			rts

			even
;## kw_strsplit
;kw_strsplit, <descriptor>, <base>, <capacity>, <text>, <sep>, <element size>  - a() = Split(text, sep)
kw_strsplit:
			movea.l (sp)+, a4			; descriptor
			move.l (sp)+, d6			; base
			move.l (sp)+, d3			; capacity (elements)
			movea.l (sp)+, a2			; text
			movea.l (sp)+, a3			; sep
			move.l (sp)+, d5			; element size
			movea.l d6, a5				; the element being filled
			moveq #0, d7				; count
			tst.b (a2)
			beq kw_sp_fin
kw_sp_elem:
			cmp.w d3, d7
			bcc kw_sp_fin
			addq.w #1, d7
			movea.l a5, a1
			move.w d5, d4
			subq.w #1, d4				; room in the element
kw_sp_ch:
			tst.b (a2)
			beq kw_sp_last
			tst.b (a3)
			beq kw_sp_nosep
			movea.l a2, a0
			movea.l a3, a6
kw_sp_m:
			move.b (a6)+, d0
			beq kw_sp_hit
			cmp.b (a0)+, d0
			beq kw_sp_m
kw_sp_nosep:
			move.b (a2)+, d0
			tst.w d4
			beq kw_sp_ch
			move.b d0, (a1)+
			subq.w #1, d4
			bra kw_sp_ch
kw_sp_hit:
			movea.l a0, a2
			clr.b (a1)
			adda.w d5, a5
			bra kw_sp_elem
kw_sp_last:
			clr.b (a1)
kw_sp_fin:
			move.w d6, (a4)
			clr.w 2(a4)
			clr.w 4(a4)
			move.w d7, 6(a4)
			move.w #1, 8(a4)
			move.w d5, 10(a4)
			rts

			even
;## kw_strcstr ntc_itoa
;kw_strcstr, <dest>, <nvar>  - number to text (CStr, "x" & n)
kw_strcstr:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_next, a6
			bra ntc_itoa

			even
;## kw_strspace ntc_getn
;kw_strspace, <dest>, <nvar>  - Space$(n)
kw_strspace:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			lea kw_sps_n, a6
			bra ntc_getn
kw_sps_n:
			moveq #' ', d1
; d0.w = count (NTC_STRMAX at most), d1.b = char, a1 = dest. rts
ntc_strfill:
			cmpi.w #NTC_STRMAX, d0
			bls ntc_sf_ok
			move.w #NTC_STRMAX, d0
ntc_sf_ok:
			subq.w #1, d0
			bmi ntc_sf_end
ntc_sf_lp:
			move.b d1, (a1)+
			dbra d0, ntc_sf_lp
ntc_sf_end:
			clr.b (a1)
			rts

			even
;## kw_sget
;kw_sget, <arraybase>, <indexvar>, <dest>, <element size>  - dest = array(index)
kw_sget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			movea.l (sp)+, a1			; dest
			move.l (sp)+, d1			; size
			mulu.w d1, d0
			adda.l d0, a0
			subq.w #1, d1
kw_sg_lp:
			move.b (a0)+, (a1)+
			dbra d1, kw_sg_lp
			rts

			even
;## kw_sset kw_strcpy
;kw_sset, <arraybase>, <indexvar>, <src>, <element size>  - array(index) = src, cut at the element
kw_sset:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.w (a0), d0
			movea.l (sp)+, a0			; src
			move.l (sp)+, d1			; size
			andi.l #$FFFF, d1
			mulu.w d1, d0
			adda.l d0, a1
			subq.w #1, d1				; capacity
			bra ntc_strcpy_lp

; ============================================================
; Array parameters and dynamic arrays. A procedure gets the address of a
; 12 byte descriptor: dc.w base (RAM, 16 bits), lower bound 1, lower bound 2,
; count 1, count 2, element size.
; ============================================================

			even
;## ntc_paddr
; a0 = descriptor, a1 = index var: a0 = element address, d1 = element size. jmp (a6)
ntc_paddr:
			move.w (a1), d0
			sub.w 2(a0), d0				; element number
ntc_pa_tail:					; d0.w = element number, a0 = descriptor
			move.w 10(a0), d1
			movea.w (a0), a0
			muls.w d1, d0
			adda.l d0, a0
			jmp (a6)

			even
;## kw_pget ntc_paddr
;kw_pget, <descriptor>, <indexvar>, <dest>  - dest = parameter array(index)
kw_pget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_pg_a, a6
			bra ntc_paddr
kw_pg_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: into the Integer's low byte
			bne kw_pg_n1
			clr.b (a1)+
kw_pg_n1:
			subq.w #1, d1
kw_pg_lp:
			move.b (a0)+, (a1)+
			dbra d1, kw_pg_lp
			rts

			even
;## kw_pset ntc_paddr
;kw_pset, <descriptor>, <indexvar>, <src>  - parameter array(index) = src
kw_pset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_ps_a, a6
			bra ntc_paddr
kw_ps_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: from the Integer's low byte
			bne kw_ps_n1
			addq.l #1, a1
kw_ps_n1:
			subq.w #1, d1
kw_ps_lp:
			move.b (a1)+, (a0)+
			dbra d1, kw_ps_lp
			rts

			even
;## kw_lbound
;kw_lbound, <descriptor + 2 * (dimension - 1)>, <dest>  - LBound
kw_lbound:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w 2(a0), (a1)
			rts

			even
;## kw_ubound
;kw_ubound, <descriptor + 2 * (dimension - 1)>, <dest>  - UBound = lower bound + count - 1
kw_ubound:
			movea.l (sp)+, a0
			move.w 2(a0), d0
			add.w 6(a0), d0
			subq.w #1, d0
			movea.l (sp)+, a1
			move.w d0, (a1)
			rts

; ============================================================
; Long (32 bit signed): a 68000 long. Every argument is an address
; (a literal is a dc.l in the ROM).
; ============================================================

			even
;## kw_l_mov
kw_l_mov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), (a1)
			rts

			even
;## kw_l_cpeq
kw_l_cpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			cmp.l (a1), d0
			rts

			even
;## ntc_ltoa ntc_data
; the Long d0 to text at a1, a 0 at the end (a1 on it). jmp (a6). Uses d0-d3, a0
ntc_ltoa:
			tst.l d0
			bpl ntc_lta_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_lta_pos:
			lea ntc_lta_tmp+12, a0
			clr.b -(a0)
ntc_lta_lp:
			; d0 unsigned / 10: high word first
			move.l d0, d2
			clr.w d2
			swap d2
			divu.w #10, d2				; d2 = rem:quot of the high word
			move.w d2, d3				; the quotient's high word
			move.w d0, d2				; rem (high) : low word
			divu.w #10, d2
			swap d3
			move.w d2, d3				; d3 = the quotient
			swap d2
			addi.b #'0', d2
			move.b d2, -(a0)
			move.l d3, d0
			bne ntc_lta_lp
ntc_lta_cp:
			move.b (a0)+, (a1)+
			bne ntc_lta_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #$01000000, d1
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "GURU 001", 0
			even

			even
;## ntc_ng_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ng_boot:
			move.w #$2700, sr          ; interrupts off during setup
			move.b d0, REG_DIPSW       ; kick the watchdog (any write)     ;!!NG value
			; clear the fix layer, set up the palette and a text font in fix tiles
			jsr ntc_ng_fixclear        ; (below)
			; hand control to the thread - the compiler's start code follows;
			; it sets A7 to the thread and runs. Interrupts get re-enabled there.
			; (ntc_plat_data / screen are pulled in as deps.)
			rts

			even
;## ntc_plat_data ntc_data
ntc_curx:   dc.w 0                     ; fix-layer cursor column (0..39)
ntc_cury:   dc.w 0                     ; row (0..31)
ntc_frames: dc.w 0                     ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; the platform routines are entered with jsr and end with rts (real stack),
; keeping d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ng_fixaddr - d1.w = the VRAM word address of (ntc_curx, ntc_cury) in the
; fix map. The fix map is column-major: addr = NG_FIXMAP + col*32 + row.  ;!!NG layout
ntc_ng_fixaddr:
			move.w ntc_curx, d1
			lsl.w #5, d1               ; col * 32
			add.w ntc_cury, d1
			add.w #NG_FIXMAP, d1
			rts

; ntc_plat_putc - d0.b = character 32..126: write it as a fix tile, advance
ntc_plat_putc:
			jsr ntc_ng_fixaddr
			move.w d1, REG_VRAMADDR
			move.w #1, REG_VRAMMOD     ; (irrelevant for a single write)
			and.w #$00FF, d0
			; fix tile word = palette<<12 | char code ;!!NG tile numbering / font must be uploaded
			move.w d0, REG_VRAMRW
			addq.w #1, ntc_curx
			cmp.w #40, ntc_curx
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - CR LF: column 0, next row (scroll not done yet) ;!!NG scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #32, ntc_cury
			blt.s ntc_nl_done
			move.w #31, ntc_cury
ntc_nl_done:
			rts

; ntc_ng_fixclear - blank the whole fix layer (space tile)   ;!!NG space tile index
ntc_ng_fixclear:
			move.w #NG_FIXMAP, REG_VRAMADDR
			move.w #1, REG_VRAMMOD
			move.w #40*32-1, d1
ntc_fc_lp:
			move.w #$0020, REG_VRAMRW
			dbra d1, ntc_fc_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_data ntc_data
ntc_plat_cls:
			jmp ntc_ng_fixclear

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0. Reads P1 (active low). Maps the stick
; to the CPC cursor codes and A/B/C to "A"/"B"/"C"; Start = 13.  ;!!NG bit map
ntc_plat_scankey:
			moveq #0, d0
			move.b REG_P1CNT, d1
			not.b d1                    ; active low -> 1 = pressed
			btst #4, d1                 ; A
			beq.s ntc_sk_b
			moveq #'A', d0
			rts
ntc_sk_b:
			btst #5, d1                 ; B
			beq.s ntc_sk_start
			moveq #'B', d0
			rts
ntc_sk_start:
			move.b REG_STATUS_B, d1
			not.b d1
			btst #0, d1                 ; Start P1
			beq.s ntc_sk_none
			moveq #13, d0
ntc_sk_none:
			rts

; ntc_plat_getkey - wait for a key
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - a cart can't "exit"; spin (a real build returns to the BIOS
; menu / soft-resets) ;!!NG
ntc_plat_exit:
			bra.s ntc_plat_exit


			even
